(()=>{const variants=[["Chrome Pulse", "铬色脉冲", "荧光绿 / 铬金属 / 锐利扭转", ["BEYOND", "FORM.", "CHAO / DESIGN"], "尖刺环体缓慢旋转，字形错位呼吸；移动指针改变光线与构图。"], ["Liquid Bloom", "液态绽放", "雾紫 / 冷银 / 流动衬线", ["Liquid", "thinking.", "CHAO / DESIGN"], "液态花瓣围绕字形舒展，衬线文字随指针轻浮，构成柔软的金属海报。"], ["Optical Field", "视差场域", "骨白 / 酸绿 / 光学干涉", ["NEW", "SENSE.", "CHAO / DESIGN"], "摩尔纹不断伸缩、交叠；厚重文字与流动线场形成光学张力。"], ["Neo Thorn", "新生荆棘", "炭黑 / 品红 / 新部落", ["ALTER", "FORM.", "CHAO / DESIGN"], "银色荆棘逐层转动，纵向文字穿过雕塑，保留黑色空间与锋利节奏。"], ["Electric Silk", "电光缎带", "钴蓝 / 橘色 / 银色交织", ["MAKE", "WAVES.", "CHAO / DESIGN"], "两条扭转缎带在大字之间穿行；按压海报时，波动与文字一起回应。"]];let active=1,paused=false;const host=document.querySelector('#poster-host');const templates=[...document.querySelectorAll('.study-preview .acid-poster')].map(p=>p.outerHTML);function choose(mode,scroll){active=mode;host.querySelector('.acid-poster')?.acidPoster?.destroy();host.innerHTML=templates[mode-1].replace('acid-mini','');new AcidPoster(host.firstElementChild,{mode,paused});const v=variants[mode-1];document.querySelector('#active-number').textContent='A0'+mode+' / '+v[0].toUpperCase();document.querySelector('#active-title').textContent=v[1];document.querySelector('#active-description').textContent=v[4];document.querySelector('#choose-motion').textContent='暂选 A0'+mode+' ↗';document.querySelector('.swatches').dataset.mode=mode;document.querySelectorAll('button[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.mode)===mode)));if(scroll)document.querySelector('#live-study').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'})}document.querySelectorAll('button[data-mode]').forEach(b=>b.addEventListener('click',()=>choose(Number(b.dataset.mode),true)));document.querySelector('#pause-motion').addEventListener('click',e=>{paused=!paused;document.querySelectorAll('.acid-poster').forEach(p=>p.acidPoster?.setPaused(paused));e.currentTarget.setAttribute('aria-pressed',String(paused));e.currentTarget.textContent=paused?'播放动态 ▷':'暂停动态 Ⅱ'});document.querySelector('#choose-motion').addEventListener('click',()=>{document.querySelector('#choice-message').textContent='已暂选 A0'+active+' '+variants[active-1][1]+'。请在聊天中确认这个编号，我会将它应用到正式主页。';try{localStorage.setItem('chao-acid-choice',String(active))}catch{}});document.querySelector('.swatches').dataset.mode='1';})();